INSERT INTO verse (songid, `text`) VALUES (1, '1) ¡Santo! ¡Santo! ¡Santo! Señor Omnipotente,\nSiempre el labio mío loores te dará;\n¡Santo! ¡Santo! ¡Santo! te adoro reverente,\nDios en tres Personas, bendita Trinidad.');
INSERT INTO verse (songid, `text`) VALUES (1, '2) ¡Santo! ¡Santo! ¡Santo! en numeroso coro,\nSantos escogidos te adoran sin cesar,\nDe alegría llenos, y sus coronas de oro\nRinden ante el trono y el cristalino mar.');
INSERT INTO verse (songid, `text`) VALUES (1, '3) ¡Santo! ¡Santo! ¡Santo! la inmensa muchedumbre,\nDe ángeles que cumplen tu santa voluntad,\nAnte ti se postra bañada de tu lumbre,\nAnte ti que has sido, que eres y serás.');
INSERT INTO verse (songid, `text`) VALUES (1, '4) ¡Santo! ¡Santo! ¡Santo! por más que estés velado,\nE imposible sea  tu gloria contemplar;\nSanto tú eres solo y nada hay a tu lado,\nEn poder perfecto, pureza y caridad.');
INSERT INTO verse (songid, `text`) VALUES (1, '5) ¡Santo! ¡Santo! ¡Santo! la gloria de tu nombre,\nVemos en tus obras en cielo, tierra y mar.¡Santo! ¡Santo! ¡Santo! te adora todo hombre\n');
INSERT INTO verse (songid, `text`) VALUES (2, '1) ¡Oh Padre, eterno Dios!\nAlzamos nuestra voz con santo ardor,\nPor cuanto tú nos das, tu ayuda sin igual,\nHallando nuestra paz en ti, Señor.');
INSERT INTO verse (songid, `text`) VALUES (2, '2) ¡Bendito Salvador!\nTe damos con amor el corazón.\nY tú nos puedes ver que humildes a tu altar,\nVenimos a traer, precioso don.');
INSERT INTO verse (songid, `text`) VALUES (2, '3) ¡Espíritu de Dios!\nEscucha nuestra voz; y tu bondadDerrame en nuestro ser divina claridad\n');
